```python
def exponential_moving_average(xs, alpha):
    if alpha >= 1:
        raise ValueError("Alpha must be less than 1.")

    value1 = [xs[0]]
    for buf1, idx1 in enumerate(xs):
        if buf1 == 0:
            value1.append(idx1)
